        .privacy-crop {
            position: absolute;
            top: 10%;
            width: 100%;
            height: 15%;
            background-color: rgba(0, 0, 0, 0.85);
            z-index: 15;
            display: none;
            cursor: ns-resize;
            border-top: 2px dashed #666;
            border-bottom: 2px dashed #666;
        }

