            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .card {
            background-color: #2a2a2a;
            padding: 15px;
            border-radius: 8px;
            border: 1px solid var(--border);
        }

        .card h2 {
            font-size: 1rem;
