            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 10px;
        }

        .score-display {
            font-size: 1.5rem;
            font-weight: bold;
            color: var(--accent);
        }

        .retake-warning {
            color: var(--warning);
            font-weight: bold;
            display: none;
            font-size: 0.9rem;
        }

