</head>
<body>

    <header>
        <h1>Consistency Studio</h1>
        <div id="topScore" class="score-display">0/100</div>
    </header>

    <div class="main-container">
        <!-- Viewport -->
        <div class="viewport-section">
            <div class="image-wrapper" id="imageWrapper">
                <img id="refImage" alt="">
                <img id="currentImage" alt="">
                <div class="grid-overlay" id="gridOverlay"></div>
                <div class="privacy-crop" id="privacyCrop"></div>
            </div>
        </div>

        <!-- Controls -->
        <div class="controls-section">

            <div class="card">
                <h2>1. Load Images (Local Only)</h2>
                <div class="file-input-group">
                    <label>Reference Photo (Last Session)</label>
                    <input type="file" id="refInput" accept="image/*">
                </div>
                <div class="file-input-group">
                    <label>Current Photo</label>
                    <input type="file" id="currentInput" accept="image/*">
                </div>
                <div class="slider-group">
                    <label style="font-size:0.85rem; color:#aaa; width: 60px;">Overlay</label>
                    <input type="range" id="opacitySlider" min="0" max="100" value="100">
                </div>
            </div>

            <div class="card">
                <h2>2. Alignment & Overlays</h2>
                <div class="checkbox-group">
                    <input type="checkbox" id="toggleGrid">
                    <label for="toggleGrid">Show Rule of Thirds Grid</label>
                </div>
                <div class="checkbox-group">
                    <input type="checkbox" id="togglePrivacy">
                    <label for="togglePrivacy">Show Privacy Crop Guide</label>
                </div>
                <p style="font-size: 0.75rem; color: #888; margin-top: 5px; display: none;" id="privacyHint">Drag the privacy guide up/down to check face/identifiable feature masking.</p>
            </div>

            <div class="card">
                <h2>3. Consistency Checklist</h2>
                <div class="checkbox-group">
                    <input type="checkbox" class="consistency-check" id="chkPose" value="25">
                    <label for="chkPose">Pose matches reference exactly</label>
                </div>
                <div class="checkbox-group">
                    <input type="checkbox" class="consistency-check" id="chkAngle" value="25">
                    <label for="chkAngle">Camera height/angle is identical</label>
                </div>
                <div class="checkbox-group">
                    <input type="checkbox" class="consistency-check" id="chkLight" value="25">
                    <label for="chkLight">Lighting matches (time of day/room)</label>
                </div>
                <div class="checkbox-group">
                    <input type="checkbox" class="consistency-check" id="chkBg" value="25">
                    <label for="chkBg">Background is clear of distractions</label>
                </div>

                <div class="status-panel">
                    <span class="retake-warning" id="retakeWarning">⚠️ SUBOPTIMAL - RETAKE RECOMMENDED</span>
                </div>
            </div>

            <div class="card">
                <h2>4. Session Receipt</h2>
                <textarea id="receiptArea" readonly>Load images and complete checklist to generate receipt.</textarea>
                <button id="btnCopy">Copy Receipt to Clipboard</button>
            </div>

        </div>
    </div>

    <script>
        // DOM Elements
        const refInput = document.getElementById('refInput');
        const currentInput = document.getElementById('currentInput');
        const refImage = document.getElementById('refImage');
        const currentImage = document.getElementById('currentImage');

        const opacitySlider = document.getElementById('opacitySlider');
        const toggleGrid = document.getElementById('toggleGrid');
        const togglePrivacy = document.getElementById('togglePrivacy');
        const gridOverlay = document.getElementById('gridOverlay');
        const privacyCrop = document.getElementById('privacyCrop');
        const privacyHint = document.getElementById('privacyHint');

        const checks = document.querySelectorAll('.consistency-check');
        const topScore = document.getElementById('topScore');
        const retakeWarning = document.getElementById('retakeWarning');
        const receiptArea = document.getElementById('receiptArea');
        const btnCopy = document.getElementById('btnCopy');

        let score = 0;

        // Image Loading (Client-side Object URLs)
        function handleImageUpload(input, imgElement) {
            input.addEventListener('change', (e) => {
                const file = e.target.files[0];
                if (file) {
                    imgElement.src = URL.createObjectURL(file);
                    updateReceipt();
                }
            });
        }
        handleImageUpload(refInput, refImage);
        handleImageUpload(currentInput, currentImage);

        // Opacity Slider for Alignment
        opacitySlider.addEventListener('input', (e) => {
            currentImage.style.opacity = e.target.value / 100;
        });

        // Toggles
        toggleGrid.addEventListener('change', (e) => {
            gridOverlay.style.display = e.target.checked ? 'block' : 'none';
        });

        togglePrivacy.addEventListener('change', (e) => {
            privacyCrop.style.display = e.target.checked ? 'block' : 'none';
            privacyHint.style.display = e.target.checked ? 'block' : 'none';
        });

        // Draggable Privacy Mask
        let isDragging = false;
        let startY;
        let startTop;

        privacyCrop.addEventListener('mousedown', (e) => {
            isDragging = true;
            startY = e.clientY;
            startTop = parseInt(window.getComputedStyle(privacyCrop).top, 10);
        });

        window.addEventListener('mousemove', (e) => {
            if (!isDragging) return;
            const containerHeight = document.getElementById('imageWrapper').offsetHeight;
            let newTop = startTop + (e.clientY - startY);
            // Constrain to container
            newTop = Math.max(0, Math.min(newTop, containerHeight - privacyCrop.offsetHeight));
            privacyCrop.style.top = newTop + 'px';
        });

        window.addEventListener('mouseup', () => {
            isDragging = false;
        });

        // Scoring & Receipt Generation
        function updateScore() {
            score = Array.from(checks).reduce((acc, check) => {
                return acc + (check.checked ? parseInt(check.value) : 0);
            }, 0);

            topScore.innerText = `${score}/100`;

            if (score < 100 && score > 0) {
                retakeWarning.style.display = 'block';
            } else {
                retakeWarning.style.display = 'none';
            }
            updateReceipt();
        }

        function updateReceipt() {
            const date = new Date().toISOString().split('T')[0];
            const time = new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});

            const failedChecks = Array.from(checks)
                .filter(c => !c.checked)
                .map(c => c.nextElementSibling.innerText)
                .join(' | ');

            let receipt = `PROGRESS SHOT RECEIPT\nDate: ${date} ${time}\nConsistency Score: ${score}/100\n`;

            if (score === 100) {
                receipt += `Status: VALIDATED (Perfect Match)\n`;
            } else {
                receipt += `Status: DEVIATION DETECTED\nDeviations: ${failedChecks || 'None selected yet.'}\n`;
            }

            if (document.getElementById('togglePrivacy').checked) {
                receipt += `Privacy Mask: Active\n`;
            }

            receiptArea.value = receipt;
        }

        checks.forEach(check => {
            check.addEventListener('change', updateScore);
        });

        // Copy to Clipboard
        btnCopy.addEventListener('click', () => {
            receiptArea.select();
            document.execCommand('copy');
            const originalText = btnCopy.innerText;
            btnCopy.innerText = 'Copied to Clipboard!';
            btnCopy.style.backgroundColor = '#00c853';
            setTimeout(() => {
                btnCopy.innerText = originalText;
                btnCopy.style.backgroundColor = 'var(--accent)';
            }, 2000);
        });

        // Initialize
        updateScore();
    </script>
</body>
</html>

