                group.appendChild(grid);
                setupBoard.appendChild(group);
            });

            updateBaselineStatus();
            renderHistory();
        }

        // Logic
        function handleCardSelect(factorId, value) {
            currentSetup[factorId] = value;
            evaluateState();
        }

        function evaluateState() {
            // Update Card UI
            document.querySelectorAll('.setup-card').forEach(card => {
                const factor = card.dataset.factor;
                const val = card.dataset.value;

                card.classList.remove('selected', 'baseline-match', 'baseline-mismatch');

                if (currentSetup[factor] === val) {
                    card.classList.add('selected');

                    if (baselineSetup) {
                        if (baselineSetup[factor] === val) {
                            card.classList.add('baseline-match');
                        } else {
                            card.classList.add('baseline-mismatch');
                        }
                    }
                }
            });

            calculateScore();
            generateReceipt();
        }

        function calculateScore() {
            const keysFilled = Object.keys(currentSetup).length;
            if (keysFilled < schema.length) {
                topScore.textContent = '--/100';
                topScore.style.color = 'var(--text-muted)';
                retakeWarning.style.display = 'none';
                return;
