            if (baselineSetup && Object.keys(currentSetup).length === schema.length) {
                receipt += `Comparability Score: ${currentScore}/100\n\n`;
            } else {
                receipt += `Comparability Score: N/A\n\n`;
            }

            receipt += `[ SHOT SETUP ]\n`;
            schema.forEach(s => {
                const val = currentSetup[s.id] || 'Not Selected';
                receipt += `- ${s.label}: ${val}\n`;
            });

            const privacyChecks = document.querySelectorAll('.privacy-check:checked');
            receipt += `\n[ PRIVACY VERIFICATION ]\nChecks Passed: ${privacyChecks.length}/3\n`;

            receiptArea.value = receipt;
        }

        function updateBaselineStatus() {
            if (baselineSetup) {
                baselineStatus.textContent = "Baseline established. New setups will be compared against it.";
            } else {
                baselineStatus.textContent = "No baseline saved. Configure your ideal setup and save it.";
            }
            evaluateState();
        }

