            if(confirm('Clear all session history and the saved baseline?')) {
                localStorage.removeItem('consistencyHistory');
                localStorage.removeItem('consistencyBaseline');
                sessionHistory = [];
                baselineSetup = null;
                currentSetup = {};
                renderHistory();
                updateBaselineStatus();
                evaluateState();
