                li.className = 'history-item';

                let scoreClass = 'score-low';
                if (session.score === 100) scoreClass = 'score-100';
                else if (session.score >= 60) scoreClass = 'score-mid';

                const dateSpan = document.createElement('span');
                dateSpan.textContent = session.date;

                const scoreSpan = document.createElement('span');
                scoreSpan.className = `history-score ${scoreClass}`;
                scoreSpan.textContent = session.score !== null ? session.score + '/100' : 'N/A';

                li.appendChild(dateSpan);
                li.appendChild(scoreSpan);
                historyList.appendChild(li);
            });
        }

        // Event Listeners
        document.querySelectorAll('.privacy-check').forEach(chk => {
            chk.addEventListener('change', generateReceipt);
        });

        document.getElementById('btnSaveBaseline').addEventListener('click', () => {
            if (Object.keys(currentSetup).length < schema.length) {
                showFeedback('baselineFeedback', 'Please select an option for all 6 factors first.', true);
                return;
            }
            baselineSetup = { ...currentSetup };
            localStorage.setItem('consistencyBaseline', JSON.stringify(baselineSetup));
            updateBaselineStatus();
            showFeedback('baselineFeedback', 'Baseline saved successfully.');
        });

        document.getElementById('btnCopy').addEventListener('click', () => {
            const btn = document.getElementById('btnCopy');
            const originalText = btn.textContent;

            navigator.clipboard.writeText(receiptArea.value).then(() => {
                btn.textContent = 'Copied!';
                btn.style.backgroundColor = 'var(--success)';
                showFeedback('copyFeedback', 'Receipt copied to clipboard.');
                setTimeout(() => {
                    btn.textContent = originalText;
                    btn.style.backgroundColor = 'var(--accent)';
                }, 2000);
            }).catch(() => {
                showFeedback('copyFeedback', 'Failed to copy. Please copy manually.', true);
            });
        });

        document.getElementById('btnLogSession').addEventListener('click', () => {
            if (Object.keys(currentSetup).length < schema.length) {
                showFeedback('logFeedback', 'Please complete the setup board first.', true);
                return;
            }

            const date = new Date().toISOString().split('T')[0];
            const sessionData = {
                date: date,
                setup: { ...currentSetup },
                score: baselineSetup ? currentScore : null
            };

            sessionHistory.push(sessionData);
            localStorage.setItem('consistencyHistory', JSON.stringify(sessionHistory));
            renderHistory();
            showFeedback('logFeedback', 'Session logged successfully.');
        });

        // Inline Confirmation Flow for Clear History
        const btnInitiateClear = document.getElementById('btnInitiateClear');
        const clearConfirmUI = document.getElementById('clearConfirmUI');
        const btnConfirmClear = document.getElementById('btnConfirmClear');
        const btnCancelClear = document.getElementById('btnCancelClear');

        btnInitiateClear.addEventListener('click', () => {
            btnInitiateClear.style.display = 'none';
            clearConfirmUI.style.display = 'flex';
        });

        btnCancelClear.addEventListener('click', () => {
            clearConfirmUI.style.display = 'none';
            btnInitiateClear.style.display = 'block';
        });

        btnConfirmClear.addEventListener('click', () => {
            localStorage.removeItem('consistencyHistory');
            localStorage.removeItem('consistencyBaseline');
            sessionHistory = [];
            baselineSetup = null;
            currentSetup = {};

            renderHistory();
            updateBaselineStatus();
            evaluateState();
            topScore.textContent = '--/100';

            clearConfirmUI.style.display = 'none';
            btnInitiateClear.style.display = 'block';
        });

        // Boot
        initBoard();
    </script>
</body>
